-- Qualité des données : colonnes facultatives
ALTER TABLE public.dispos_intervenants ADD COLUMN IF NOT EXISTS employes_refuses uuid[] NOT NULL DEFAULT '{}';
ALTER TABLE public.employes ADD COLUMN IF NOT EXISTS caces text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS fusionne_dans uuid REFERENCES public.employes(id),
  ADD COLUMN IF NOT EXISTS fusionne_le timestamptz,
  ADD COLUMN IF NOT EXISTS historique_qualite jsonb NOT NULL DEFAULT '[]';
ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS fusionne_dans uuid REFERENCES public.clients(id),
  ADD COLUMN IF NOT EXISTS fusionne_le timestamptz,
  ADD COLUMN IF NOT EXISTS historique_qualite jsonb NOT NULL DEFAULT '[]';
ALTER TABLE public.devis ADD COLUMN IF NOT EXISTS classe_sans_suite_le timestamptz,
  ADD COLUMN IF NOT EXISTS classe_sans_suite_par uuid;
COMMENT ON COLUMN public.employes.historique_qualite IS 'Journal des corrections Qualité des données (champ, avant, après, par, le)';
COMMENT ON COLUMN public.clients.historique_qualite IS 'Journal des corrections Qualité des données (champ, avant, après, par, le)';

-- Planning logistique étape 4 : besoins qualifiés lus et écrits
CREATE OR REPLACE FUNCTION public.planning_terrain_semaine(_debut date, _fin date)
 RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$ BEGIN IF NOT planning_terrain_lire_autorise() OR _fin<_debut OR _fin-_debut>31 THEN RAISE EXCEPTION 'Accès ou période invalide'; END IF; RETURN jsonb_build_object('references',planning_terrain_references(),'affectations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'employe_id',employe_id,'dispos_intervenant_id',dispos_intervenant_id,'etape_id',etape_logistique_id,'date',date,'affaire_id',affaire_id,'role',role_terrain,'validation',validation_logistique,'confirmation',statut_confirmation,'historique',historique_terrain)) FROM assignations WHERE date BETWEEN _debut AND _fin),'[]'::jsonb),'etapes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'date',e.date_debut,'fin',coalesce(e.date_fin,e.date_debut),'heure',e.heure_debut,'heure_fin',e.heure_fin,'horaire_libre',e.horaire_libre,'note',e.note,'nb_vehicules',e.nb_vehicules,'nb_chefs_equipe',e.nb_chefs_equipe,'permis_requis',e.permis_requis,'caces_requis',e.caces_requis,'caces_autre_requis',e.caces_autre_requis,'vehicule',coalesce(v.nom,e.immatriculation_libre),'type',e.type,'nb_personnes',e.nb_personnes,'responsable',e.responsable,'lieu',coalesce(e.lieu_libre,a.lieu),'numero',a.numero,'nom',a.nom,'affaire_id',a.id)) FROM affaire_etapes_logistiques e JOIN affaires a ON a.id=e.affaire_id LEFT JOIN vehicules v ON v.id=e.vehicule_id WHERE e.date_debut<=_fin AND coalesce(e.date_fin,e.date_debut)>=_debut AND e.statut<>'annule'),'[]'::jsonb),'dispos',coalesce((SELECT jsonb_agg(jsonb_build_object('intervenant_id',d.intervenant_id,'employe_id',i.employe_id,'jour',d.jour,'journee',d.journee,'soiree',d.soiree,'pas_dispo',d.pas_dispo)) FROM dispos_jours d JOIN dispos_intervenants i ON i.id=d.intervenant_id WHERE d.jour BETWEEN _debut AND _fin),'[]'::jsonb)); END $function$;

CREATE OR REPLACE FUNCTION public.app_modifier_etape_logistique(_id uuid, _patch jsonb)
 RETURNS jsonb LANGUAGE plpgsql SET search_path TO 'public'
AS $function$ DECLARE k text; sets text:=''; result jsonb; e public.affaire_etapes_logistiques; d date; f date; BEGIN IF _patch->>'statut'='annule' AND length(trim(COALESCE(_patch->>'commentaire_equipe',''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Motif annulation obligatoire'; END IF; SELECT * INTO e FROM affaire_etapes_logistiques WHERE id=_id; PERFORM public.app_assert_affaire_write(e.affaire_id,'logistique.etape.edit'); d:=CASE WHEN _patch ? 'date_debut' THEN (_patch->>'date_debut')::date ELSE e.date_debut END; f:=CASE WHEN _patch ? 'date_fin' THEN (_patch->>'date_fin')::date ELSE e.date_fin END; IF d IS NULL OR f<d THEN RAISE EXCEPTION 'Dates invalides'; END IF; IF jsonb_typeof(_patch)<>'object' OR _patch='{}'::jsonb THEN RAISE EXCEPTION 'Modification vide'; END IF; FOR k IN SELECT jsonb_object_keys(_patch) LOOP IF k NOT IN ('type','sens','date_debut','date_fin','heure_debut','heure_fin','horaire_libre','lieu_libre','nb_personnes','responsable','vehicule_id','immatriculation_libre','acces','note','commentaire_equipe','statut','nb_chefs_equipe','nb_vehicules','permis_requis','caces_requis','caces_autre_requis') THEN RAISE EXCEPTION 'Champ interdit: %',k; END IF; sets:=sets || CASE WHEN sets='' THEN '' ELSE ',' END || format('%I=p.%I',k,k); END LOOP; EXECUTE format('UPDATE public.affaire_etapes_logistiques t SET %s FROM jsonb_populate_record(NULL::public.affaire_etapes_logistiques,$1) p WHERE t.id=$2 RETURNING jsonb_build_object(''id'',t.id)',sets) INTO result USING _patch,_id; IF result IS NULL THEN RAISE EXCEPTION 'Modification refusée par les droits'; END IF; RETURN result; END $function$;

CREATE OR REPLACE FUNCTION public.app_creer_etape_logistique(_payload jsonb)
 RETURNS jsonb LANGUAGE plpgsql SET search_path TO 'public'
AS $function$ DECLARE r public.affaire_etapes_logistiques; k text; result jsonb; BEGIN PERFORM app_assert_affaire_write((_payload->>'affaire_id')::uuid,'logistique.etape.edit'); FOR k IN SELECT jsonb_object_keys(_payload) LOOP IF k NOT IN ('affaire_id','type','sens','date_debut','date_fin','heure_debut','heure_fin','horaire_libre','lieu_libre','nb_personnes','responsable','vehicule_id','immatriculation_libre','acces','note','commentaire_equipe','statut','nb_chefs_equipe','nb_vehicules','permis_requis','caces_requis','caces_autre_requis') THEN RAISE EXCEPTION 'Champ interdit'; END IF; END LOOP; r:=jsonb_populate_record(NULL::public.affaire_etapes_logistiques,_payload); IF r.date_debut IS NULL OR r.date_fin<r.date_debut THEN RAISE EXCEPTION 'Dates invalides'; END IF; INSERT INTO affaire_etapes_logistiques(affaire_id,type,sens,date_debut,date_fin,heure_debut,heure_fin,horaire_libre,lieu_libre,nb_personnes,responsable,vehicule_id,immatriculation_libre,acces,note,commentaire_equipe,nb_chefs_equipe,nb_vehicules,permis_requis,caces_requis,caces_autre_requis,origine,statut,created_by) VALUES(r.affaire_id,r.type,r.sens,r.date_debut,r.date_fin,r.heure_debut,r.heure_fin,r.horaire_libre,r.lieu_libre,r.nb_personnes,r.responsable,r.vehicule_id,r.immatriculation_libre,r.acces,r.note,r.commentaire_equipe,r.nb_chefs_equipe,r.nb_vehicules,r.permis_requis,r.caces_requis,r.caces_autre_requis,'manuel','valide',auth.uid()) RETURNING jsonb_build_object('id',id,'affaire_id',affaire_id) INTO result; RETURN result; END $function$;

-- Lecteur écran atelier : noms, chef, véhicule ; jamais téléphone ni montant
CREATE OR REPLACE FUNCTION public.planning_terrain_ecran(_debut date, _fin date)
 RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$ BEGIN
  IF auth.uid() IS NULL OR NOT (planning_terrain_lire_autorise() OR has_role(auth.uid(),'ecran_atelier'::app_role)) OR _fin<_debut OR _fin-_debut>14 THEN RAISE EXCEPTION 'Accès ou période invalide'; END IF;
  RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'date',e.date_debut,'fin',coalesce(e.date_fin,e.date_debut),'heure',e.heure_debut,'heure_fin',e.heure_fin,'horaire_libre',e.horaire_libre,'type',e.type,'numero',a.numero,'nom',a.nom,'lieu',coalesce(e.lieu_libre,a.lieu),'vehicule',coalesce(v.nom,e.immatriculation_libre),'nb_personnes',e.nb_personnes,
    'equipe',coalesce((SELECT jsonb_agg(DISTINCT jsonb_build_object('nom',coalesce(em.nom,di.nom),'prenom',coalesce(em.prenom,di.prenom),'chef',s.role_terrain='chef')) FROM assignations s LEFT JOIN employes em ON em.id=s.employe_id LEFT JOIN dispos_intervenants di ON di.id=s.dispos_intervenant_id WHERE s.etape_logistique_id=e.id),'[]'::jsonb)))
    FROM affaire_etapes_logistiques e JOIN affaires a ON a.id=e.affaire_id LEFT JOIN vehicules v ON v.id=e.vehicule_id
    WHERE e.date_debut<=_fin AND coalesce(e.date_fin,e.date_debut)>=_debut AND e.statut<>'annule'),'[]'::jsonb);
END $function$;
REVOKE ALL ON FUNCTION public.planning_terrain_ecran(date,date) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.planning_terrain_ecran(date,date) TO authenticated;